SELECT 
FROM mcp_server_info

    AND del_flag = 0

        AND server_name LIKE CONCAT('%', #{bo.serverName}, '%')


        AND server_code LIKE CONCAT('%', #{bo.serverCode}, '%')


        AND server_type = #{bo.serverType}


        AND transport_type = #{bo.transportType}


        AND status = #{bo.status}


ORDER BY server_name ASC, id ASC

SELECT COUNT(1) > 0
FROM mcp_server_info
WHERE server_code = #{serverCode}

    AND id != #{excludeId}
